// CourseServiceServer is the server API for CourseService service.
// All implementations must embed UnimplementedCourseServiceServer
// for forward compatibility.
//
// CourseService предоставляет методы для управления курсами
type CourseServiceServer interface {
	// Student endpoints
	// ListCourses получает список курсов с фильтрацией
	ListCourses(context.Context, *ListCoursesRequest) (*ListCoursesResponse, error)
	// GetCourse получает детальную информацию о курсе
	GetCourse(context.Context, *GetCourseRequest) (*GetCourseResponse, error)
	// GetLesson получает информацию об уроке
	GetLesson(context.Context, *GetLessonRequest) (*GetLessonResponse, error)
	// GetStepContent получает содержимое шага
	GetStepContent(context.Context, *GetStepContentRequest) (*GetStepContentResponse, error)
	// EnrollUser записывает пользователя на курс
	EnrollUser(context.Context, *EnrollUserRequest) (*EnrollUserResponse, error)
	// CheckAccess проверяет доступ пользователя к курсу
	CheckAccess(context.Context, *CheckAccessRequest) (*CheckAccessResponse, error)
	// Admin endpoints
	// CreateCourse создает новый курс
	CreateCourse(context.Context, *CreateCourseRequest) (*CreateCourseResponse, error)
	// UpdateCourse обновляет курс
	UpdateCourse(context.Context, *UpdateCourseRequest) (*UpdateCourseResponse, error)
	// DeleteCourse удаляет курс
	DeleteCourse(context.Context, *DeleteCourseRequest) (*DeleteCourseResponse, error)
	// PublishCourse публикует/снимает с публикации курс
	PublishCourse(context.Context, *PublishCourseRequest) (*PublishCourseResponse, error)
	// CreateModule создает новый модуль
	CreateModule(context.Context, *CreateModuleRequest) (*CreateModuleResponse, error)
	// UpdateModule обновляет модуль
	UpdateModule(context.Context, *UpdateModuleRequest) (*UpdateModuleResponse, error)
	// DeleteModule удаляет модуль
	DeleteModule(context.Context, *DeleteModuleRequest) (*DeleteModuleResponse, error)
	// CreateLesson создает новый урок
	CreateLesson(context.Context, *CreateLessonRequest) (*CreateLessonResponse, error)
	// UpdateLesson обновляет урок
	UpdateLesson(context.Context, *UpdateLessonRequest) (*UpdateLessonResponse, error)
	// DeleteLesson удаляет урок
	DeleteLesson(context.Context, *DeleteLessonRequest) (*DeleteLessonResponse, error)
	// CreateStep создает новый шаг
	CreateStep(context.Context, *CreateStepRequest) (*CreateStepResponse, error)
	// UpdateStep обновляет шаг
	UpdateStep(context.Context, *UpdateStepRequest) (*UpdateStepResponse, error)
	// DeleteStep удаляет шаг
	DeleteStep(context.Context, *DeleteStepRequest) (*DeleteStepResponse, error)
	// Progress tracking
	// MarkStepComplete отмечает шаг как завершенный
	MarkStepComplete(context.Context, *MarkStepCompleteRequest) (*MarkStepCompleteResponse, error)
	// GetStepProgress получает прогресс по шагу
	GetStepProgress(context.Context, *GetStepProgressRequest) (*GetStepProgressResponse, error)
	// GetLessonProgress получает прогресс по уроку
	GetLessonProgress(context.Context, *GetLessonProgressRequest) (*GetLessonProgressResponse, error)
	// GetCourseProgress получает прогресс по курсу
	GetCourseProgress(context.Context, *GetCourseProgressRequest) (*GetCourseProgressResponse, error)
	// === Learning Tracks (Phase 0 — standalone content) ===
	// ListTracks возвращает страницу треков
	ListTracks(context.Context, *ListTracksRequest) (*ListTracksResponse, error)
	// GetTrack возвращает трек по ID
	GetTrack(context.Context, *GetTrackRequest) (*GetTrackResponse, error)
	// GetTrackByCode возвращает трек по уникальному коду (для frontend deeplinks)
	GetTrackByCode(context.Context, *GetTrackByCodeRequest) (*GetTrackResponse, error)
	// CreateTrack создаёт новый трек
	CreateTrack(context.Context, *CreateTrackRequest) (*CreateTrackResponse, error)
	// UpdateTrack обновляет трек
	UpdateTrack(context.Context, *UpdateTrackRequest) (*UpdateTrackResponse, error)
	// DeleteTrack удаляет трек (lessons остаются, связи каскадно)
	DeleteTrack(context.Context, *DeleteTrackRequest) (*DeleteTrackResponse, error)
	// PublishTrack публикует/снимает с публикации
	PublishTrack(context.Context, *PublishTrackRequest) (*PublishTrackResponse, error)
	// AddLessonToTrack привязывает урок (включая standalone) к треку
	AddLessonToTrack(context.Context, *AddLessonToTrackRequest) (*AddLessonToTrackResponse, error)
	// RemoveLessonFromTrack отвязывает урок от трека
	RemoveLessonFromTrack(context.Context, *RemoveLessonFromTrackRequest) (*RemoveLessonFromTrackResponse, error)
	// ReorderTrackLessons атомарно переустанавливает порядок уроков в треке
	ReorderTrackLessons(context.Context, *ReorderTrackLessonsRequest) (*ReorderTrackLessonsResponse, error)
	// === Vocabulary (Phase 2) ===
	// Словарь — слова с переводами для match_pairs / fill_blank / listening.
	ListVocabulary(context.Context, *ListVocabularyRequest) (*ListVocabularyResponse, error)
	GetVocabularyEntry(context.Context, *GetVocabularyEntryRequest) (*GetVocabularyEntryResponse, error)
	CreateVocabularyEntry(context.Context, *CreateVocabularyEntryRequest) (*CreateVocabularyEntryResponse, error)
	UpdateVocabularyEntry(context.Context, *UpdateVocabularyEntryRequest) (*UpdateVocabularyEntryResponse, error)
	DeleteVocabularyEntry(context.Context, *DeleteVocabularyEntryRequest) (*DeleteVocabularyEntryResponse, error)
	BulkCreateVocabulary(context.Context, *BulkCreateVocabularyRequest) (*BulkCreateVocabularyResponse, error)
	// === TTS (Phase 2 — stub) ===
	// На phase-2 SynthesizeTTS сохраняет переданный audio_url в кэш
	// (без вызова TTS-провайдера). GetTTSByText читает из кэша.
	// Реальная интеграция с Google Cloud TTS / ElevenLabs — Phase 5.
	SynthesizeTTS(context.Context, *SynthesizeTTSRequest) (*SynthesizeTTSResponse, error)
	GetTTSByText(context.Context, *GetTTSByTextRequest) (*GetTTSByTextResponse, error)
	mustEmbedUnimplementedCourseServiceServer()
}

